  logic [2:0]  img_on;
  event ld_ev;
  task automatic load_plane(input int id, input string fn);
    $readmemh(fn, pl_tmp);
    for (int i = 0; i < NW; i++) img[id][i] = pl_tmp[i];
    img_on[id] = 1'b1;
  endtask
  // gate level: plane banks and valid bits preloaded through hierarchical names of the flattened netlist
  initial begin @(ld_ev);
    if (img_on[0]) begin
      for (int a = 0; a < 128; a++) if (0*128 + a < NW) dut.u_est.u_core.\g_pl[0].u_pl_g_bank[0].u_bank .m[a] = img[0][0*128 + a];
      for (int a = 0; a < 128; a++) if (1*128 + a < NW) dut.u_est.u_core.\g_pl[0].u_pl_g_bank[1].u_bank .m[a] = img[0][1*128 + a];
