      for (int a = 0; a < 128; a++) if (8*128 + a < NW) dut.u_est.u_core.\g_pl[0].u_pl_g_bank[8].u_bank .m[a] = img[0][8*128 + a];
      for (int a = 0; a < 128; a++) if (9*128 + a < NW) dut.u_est.u_core.\g_pl[0].u_pl_g_bank[9].u_bank .m[a] = img[0][9*128 + a];
      $deposit(dut.u_est.u_core.\g_pl[0].u_pl_v_reg[0] .int_fwire_N30, 1'b1);
