      $deposit(dut.u_est.u_core.\g_pl[2].u_pl_v_reg[1198] .int_fwire_N30, 1'b1);
      $deposit(dut.u_est.u_core.\g_pl[2].u_pl_v_reg[1199] .int_fwire_N30, 1'b1);
    end
  end
  int wp;
  always_ff @(posedge clk) begin
    if (rst) begin wp <= 0; w_valid <= #1.0 1'b0; end
    else begin
      if (w_valid && w_ready) wp <= wp + 1;
      w_valid <= #1.0 (w_valid && w_ready) ? (wp + 1 < nwords) : (wp < nwords);
    end
  end
  assign #1.0 w_data = words[wp];

  always @(posedge clk) if (!rst) begin
    if (fp_fire && fi >= nframes) fi++;
    else if (fp_fire) begin
      logic [31:0] e_cs, e_sn, e_bx, e_by;
      void'($fscanf(fd_fp, "%h %h %h %h\n", e_cs, e_sn, e_bx, e_by));
      if (fcs !== e_cs[11:0] || fsn !== e_sn[11:0] || fbx !== e_bx[27:0] || fby !== e_by[27:0]) err_fp++;
      fi++;
    end
    if (frame_done) nfd++;
    if (win_done) begin
      logic [31:0] e [17];
      for (int k = 0; k < 17; k++) void'($fscanf(fd_win, "%h", e[k]));
      if (win_branch !== e[0][1:0] || win_keyupd !== e[1][0]) begin
        if (err_win < 10) $display("WIN %0d mismatch", wi);
        err_win++;
      end
      wi++;
    end
  end

  initial begin
    if (!$value$plusargs("VDIR=%s", vdir)) vdir = ".";
    $readmemh({vdir, "/cfg.hex"}, cfg);
    $readmemh({vdir, "/wgrid.hex"}, wg);
    $readmemh({vdir, "/mem_final_w.hex"}, mexp);
    nwords = cfg[50]; nframes = cfg[51]; nwin = cfg[52];
    words = new[nwords];
    $readmemh({vdir, "/words.hex"}, words);
    fd_fp = $fopen({vdir, "/exp_fp.hex"}, "r"); fd_win = $fopen({vdir, "/exp_win.hex"}, "r");
    wi = 0; fi = 0; nfd = 0; err_fp = 0; err_win = 0; err_mem = 0;
    // world memory starts at zero
    repeat (4) @(posedge clk); repeat (2) begin @(posedge clk); #1.0; dbg_en = 1; dbg_we = 1; dbg_bank = 0; dbg_addr = 0; dbg_wdata = '0; end
    for (int b = 0; b < 16; b++) for (int a = 0; a < 128; a++) begin
      @(posedge clk); #1.0; dbg_en = 1; dbg_we = 1; dbg_bank = b; dbg_addr = a; dbg_wdata = '0;
    end
    @(posedge clk); #1.0; dbg_en = 0; dbg_we = 0;
    repeat (3) @(posedge clk); #1.0;
    img_on = '0;
    load_plane(cfg[45], {vdir, "/plane_prev.hex"});
    if (cfg[46] != cfg[45] && cfg[28][0]) load_plane(cfg[46], {vdir, "/plane_key.hex"});
    ->ld_ev; #0.1; rst = 0; /*
    */
    wait (wi == nwin && nfd == nframes);
    repeat (20) @(posedge clk);
    for (int b = 0; b < 16; b++) for (int a = 0; a < 128; a++) begin
      @(posedge clk); #1.0; dbg_en = 1; dbg_we = 0; dbg_bank = b; dbg_addr = a;
      @(posedge clk); #1.0; dbg_en = 0; @(posedge clk); #1.0;
      if (dbg_rdata !== mexp[b * 128 + a]) err_mem++;
    end
    $display("RESULT windows %0d/%0d fp %0d/%0d (extra fp after the segment = next window, not checked) frames_done %0d  mismatches: fp %0d win %0d world_words %0d  mem rd %0d wr %0d  cycles %0d",
             wi, nwin, fi, nframes, nfd, err_fp, err_win, err_mem, n_rd, n_wr, pcyc);
    if (err_fp + err_win + err_mem + err_status == 0) $display("PASS"); else $fatal(1, "FAIL");
    $finish;
  end
  initial begin #(64'd8_000_000_000); $display("TIMEOUT wi %0d fi %0d nfd %0d wp %0d", wi, fi, nfd, wp); $finish; end
  int pcyc = 0;
  always @(posedge clk) begin pcyc++; if (pcyc % 1000000 == 0) $display("PROG cyc %0d wi %0d fi %0d nfd %0d wp %0d / %0d", pcyc, wi, fi, nfd, wp, nwords); end
  int last_wp = -1, last_wi = -1, last_nfd = -1, stagnant = 0;
  realtime previous_edge = 0;
  always @(posedge clk) begin
    if (previous_edge != 0 && $realtime - previous_edge != 8.0) $fatal(1, "CLOCK_NOT_8NS");
    previous_edge = $realtime;
    if (!rst) begin
      if (sc_pub) seen_pub = 1;
      if (wp == last_wp && wi == last_wi && nfd == last_nfd) stagnant++;
      else stagnant = 0;
      last_wp = wp; last_wi = wi; last_nfd = nfd;
      if (stagnant > 2000000) $fatal(1, "STALL cycles %0d wi %0d wp %0d", pcyc, wi, wp);
    end
  end
endmodule
